import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import '../CSS/SellerDashboard.css'; // Or keep your theme CSS import here
import './CSS/AddProductPage.css';

export default function AddProductPage() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    title: '',
    brand: '',
    category: 'Electronics',
    price: '',
    mrp: '',
    stock: '',
    description: '',
    features: ''
  });
  const [selectedImages, setSelectedImages] = useState([]);
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleImageChange = (e) => {
    const files = Array.from(e.target.files);
    if (files.length > 10) {
      alert("You can upload a maximum of 10 images.");
      return;
    }
    setSelectedImages(files);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    const data = new FormData();
    data.append('title', formData.title);
    data.append('brand', formData.brand);
    data.append('category', formData.category);
    data.append('price', formData.price);
    data.append('mrp', formData.mrp);
    data.append('stock', formData.stock);
    data.append('description', formData.description);
    
    const featureArray = formData.features.split('\n').filter(f => f.trim() !== '');
    featureArray.forEach(feature => data.append('features', feature));

    selectedImages.forEach(file => {
      data.append('images', file);
    });

    try {
      await axios.post('http://localhost:4000/api/seller/products', data, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      alert('Product published successfully!');
      navigate('/seller');
    } catch (err) {
      console.error(err);
      alert('Failed to publish product');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="add-product-container">
      <div className="add-product-card">
        
        <div className="add-product-header">
          <h2>Add New Product</h2>
          <p>Create a professional listing with pricing, inventory, and multiple images.</p>
        </div>

        <form onSubmit={handleSubmit} className="add-product-form">
          
          <div className="form-group">
            <label>Product Title *</label>
            <input type="text" name="title" value={formData.title} onChange={handleChange} required placeholder="e.g. Everseed Rechargeable LED Torch" />
          </div>

          <div className="form-row">
            <div className="form-group">
              <label>Brand / Store Name</label>
              <input type="text" name="brand" value={formData.brand} onChange={handleChange} placeholder="e.g. Eveready" />
            </div>
            <div className="form-group">
              <label>Category *</label>
              <select name="category" value={formData.category} onChange={handleChange}>
                <option value="Electronics">Electronics</option>
                <option value="Smart phones">Smart phones</option>
                <option value="Smart watches">Smart watches</option>
                <option value="Home & Kitchen">Home & Kitchen</option>
                <option value="Fashion">Fashion</option>
              </select>
            </div>
          </div>

          <div className="form-row-three">
            <div className="form-group">
              <label>Selling Price ($/₹) *</label>
              <input type="number" name="price" value={formData.price} onChange={handleChange} required placeholder="324" />
            </div>
            <div className="form-group">
              <label>M.R.P ($/₹)</label>
              <input type="number" name="mrp" value={formData.mrp} onChange={handleChange} placeholder="399" />
            </div>
            <div className="form-group">
              <label>Available Stock *</label>
              <input type="number" name="stock" value={formData.stock} onChange={handleChange} required placeholder="50" />
            </div>
          </div>

          <div className="form-group">
            <label>Product Description</label>
            <textarea name="description" rows="4" value={formData.description} onChange={handleChange} placeholder="Detailed product overview..." />
          </div>

          <div className="form-group">
            <label>Key Features / Bullet Points (Each line becomes a bullet)</label>
            <textarea name="features" rows="4" value={formData.features} onChange={handleChange} placeholder="e.g. Rechargeable 2W Led Torch&#10;Metallic Finish&#10;Overcharge Protection" />
          </div>

          <div className="image-upload-box">
            <label>Product Images (Select up to 10 images)</label>
            <input type="file" name="images" multiple accept="image/*" onChange={handleImageChange} style={{ display: 'block', marginTop: '5px' }} />
            <div style={{ marginTop: '8px', color: '#64748b', fontSize: '13px' }}>
              ✓ <b>{selectedImages.length}</b> image(s) selected (Maximum 10 allowed)
            </div>
          </div>

          <div className="form-actions">
            <button type="button" className="btn-cancel" onClick={() => navigate('/seller')}>Cancel</button>
            <button type="submit" className="btn-submit" disabled={loading}>
              {loading ? 'Publishing...' : 'Save and Publish Product'}
            </button>
          </div>

        </form>
      </div>
    </div>
  );
}
